/** Every documented error `code`. */
export const ERROR_CODES = [
  "bad_gateway",
  "bad_request",
  "blocked_upstream",
  "client_error",
  "conflict",
  "crawl_concurrency_limit_reached",
  "fetch_failed",
  "forbidden",
  "gateway_timeout",
  "insufficient_credits",
  "internal_error",
  "invalid_input",
  "invalid_manifest",
  "invalid_version",
  "listing_degraded",
  "listing_internal_error",
  "listing_not_found",
  "listing_run_not_found",
  "listing_run_unavailable",
  "listing_timeout",
  "method_not_allowed",
  "network_error",
  "not_found",
  "parse_failed",
  "payload_too_large",
  "rate_limit_exceeded",
  "rate_limited",
  "repeat_failure_backoff",
  "request_cancelled",
  "request_timeout",
  "server_error",
  "service_unavailable",
  "session_required",
  "spend_cap_exceeded",
  "spend_limit_exceeded",
  "unauthorized",
  "validation_error",
] as const;

export type ErrorCode = (typeof ERROR_CODES)[number];

const DEFAULT_ERROR_CODES: Record<number, string> = {
  400: "bad_request",
  401: "unauthorized",
  402: "insufficient_credits",
  403: "forbidden",
  404: "not_found",
  405: "method_not_allowed",
  408: "request_timeout",
  409: "conflict",
  413: "payload_too_large",
  422: "validation_error",
  429: "rate_limited",
  500: "internal_error",
  502: "bad_gateway",
  503: "service_unavailable",
  504: "gateway_timeout",
};

const RETRYABLE_STATUSES: number[] = [408, 425, 429, 500, 502, 503, 504];

/** Fields every typed SDK error carries. */
export interface TypedErrorFields {
  /** Stable machine-readable error code (see `ERROR_CODES`). */
  code: string;
  /** Whether the same request may succeed when retried. */
  retryable: boolean;
  /** Seconds the server asked to wait before retrying, or null. */
  retryAfterSeconds: number | null;
  /** Machine-readable recovery guidance from the API, or null. */
  nextAction: Record<string, unknown> | null;
  /** Whether the failed request was charged (failed requests are not), or null. */
  charged: boolean | null;
  /** Automatic retry state: `none` unless the platform scheduled one, or null. */
  autoRetry: string | null;
  /** Server request id (body `request_id` or `X-Request-ID`), or null. */
  requestId: string | null;
}

const isObject = (v: unknown): v is Record<string, unknown> =>
  !!v && typeof v === "object" && !Array.isArray(v);

/** Render an error `detail` of any shape as text, never `[object Object]`. */
export function describeErrorDetail(detail: unknown): string {
  if (typeof detail === "string") return detail;
  if (Array.isArray(detail)) {
    return detail.map(describeErrorDetail).join("; ");
  }
  if (isObject(detail)) {
    for (const key of ["message", "msg", "detail", "error"]) {
      const value = detail[key];
      if (typeof value === "string" && value) return value;
    }
    return JSON.stringify(detail);
  }
  return detail === undefined || detail === null ? "" : String(detail);
}

function headerValue(headers: unknown, name: string): string | null {
  if (!isObject(headers)) return null;
  const raw = headers[name] ?? headers[name.toLowerCase()];
  return typeof raw === "string" || typeof raw === "number"
    ? String(raw)
    : null;
}

/** Derive the typed fields from a failed axios request. */
export function typedErrorFields(source: AxiosError): TypedErrorFields {
  const response = source.response;
  const status = response?.status;
  const body = isObject(response?.data) ? response.data : null;
  const detail = isObject(body?.detail) ? body.detail : null;
  const errorObj = isObject(body?.error) ? body.error : null;
  const layers = [body, detail, errorObj].filter(isObject);
  const pick = <T>(key: string, kind: string): T | undefined => {
    for (const layer of layers) {
      if (typeof layer[key] === kind) return layer[key] as T;
    }
    return undefined;
  };

  let code = pick<string>("code", "string");
  if (!code && typeof body?.error === "string") code = body.error;
  if (!code && typeof detail?.error === "string") code = detail.error;
  let retryable = pick<boolean>("retryable", "boolean");
  if (status === undefined) {
    const cancelled = source.code === "ERR_CANCELED";
    code = code ?? (cancelled ? "request_cancelled" : "network_error");
    retryable = retryable ?? !cancelled;
  } else {
    code = code ?? DEFAULT_ERROR_CODES[status];
    code = code ?? (status < 500 ? "client_error" : "server_error");
  }

  const headerRetry = headerValue(response?.headers, "retry-after");
  const headerSeconds = headerRetry === null ? NaN : Number(headerRetry);
  const bodyRetry = pick<number>("retry_after_seconds", "number");
  const retryAfterSeconds = Number.isFinite(headerSeconds)
    ? headerSeconds
    : (bodyRetry ?? null);
  if (retryable === undefined) {
    retryable =
      (status !== undefined && RETRYABLE_STATUSES.includes(status)) ||
      headerRetry !== null;
  }
  const nextAction = pick<Record<string, unknown>>("next_action", "object");
  const charged = pick<boolean>("charged", "boolean");
  const autoRetry = pick<string>("auto_retry", "string");
  const requestId =
    pick<string>("request_id", "string") ??
    headerValue(response?.headers, "x-request-id") ??
    headerValue(response?.headers, "request-id");
  return {
    code,
    retryable,
    retryAfterSeconds,
    nextAction: nextAction ?? null,
    charged: charged ?? null,
    autoRetry: autoRetry ?? null,
    requestId: requestId ?? null,
  };
}

/** Message text from an error body (`message`/`detail`/`error`), or "". */
export function errorBodyText(source: AxiosError): string {
  const body = source.response?.data;
  if (isObject(body)) {
    return describeErrorDetail(body.message ?? body.detail ?? body.error);
  }
  return typeof body === "string" ? body : "";
}

/** Copy the typed fields (and body message) onto an AxiosError subclass. */
export function applyTypedFields(target: AxiosError, source: AxiosError): void {
  const fields = typedErrorFields(source);
  Object.assign(target, fields);
  const text = errorBodyText(source);
  if (text) target.message = text;
}

/**
 * Base class of the generated typed errors. Extends `AxiosError`, so existing
 * `axios.isAxiosError(e)` / `e.response?.status` handling keeps working.
 */
export class AlterLabError extends AxiosError implements TypedErrorFields {
  declare code: string;
  readonly retryable: boolean;
  readonly retryAfterSeconds: number | null;
  readonly nextAction: Record<string, unknown> | null;
  readonly charged: boolean | null;
  readonly autoRetry: string | null;
  readonly requestId: string | null;
  /** HTTP status, or null when no response was received. */
  readonly statusCode: number | null;

  constructor(source: AxiosError) {
    const fields = typedErrorFields(source);
    const text = errorBodyText(source);
    super(
      text || source.message,
      source.code,
      source.config,
      source.request,
      source.response,
    );
    this.name = new.target.name;
    this.cause = source;
    this.code = fields.code;
    this.retryable = fields.retryable;
    this.retryAfterSeconds = fields.retryAfterSeconds;
    this.nextAction = fields.nextAction;
    this.charged = fields.charged;
    this.autoRetry = fields.autoRetry;
    this.requestId = fields.requestId;
    this.statusCode = source.response?.status ?? null;
  }
}

/** Typed error for code `bad_gateway`. */
export class BadGatewayError extends AlterLabError {
  static readonly errorCode = "bad_gateway";
}

/** Typed error for code `bad_request`. */
export class BadRequestError extends AlterLabError {
  static readonly errorCode = "bad_request";
}

