type ErrorClass = new (source: AxiosError) => AlterLabError;

/** Typed error class per code (legacy codes live in `LEGACY_ERROR_CLASSES`). */
export const ERROR_CLASSES: Record<string, ErrorClass> = {
  "bad_gateway": BadGatewayError,
  "bad_request": BadRequestError,
  "blocked_upstream": BlockedUpstreamError,
  "client_error": ClientError,
  "conflict": ConflictError,
  "crawl_concurrency_limit_reached": CrawlConcurrencyLimitReachedError,
  "fetch_failed": FetchFailedError,
  "forbidden": ForbiddenError,
  "gateway_timeout": GatewayTimeoutError,
  "internal_error": InternalError,
  "invalid_input": InvalidInputError,
  "invalid_manifest": InvalidManifestError,
  "invalid_version": InvalidVersionError,
  "listing_degraded": ListingDegradedError,
  "listing_internal_error": ListingInternalError,
  "listing_not_found": ListingNotFoundError,
  "listing_run_not_found": ListingRunNotFoundError,
  "listing_run_unavailable": ListingRunUnavailableError,
  "listing_timeout": ListingTimeoutError,
  "method_not_allowed": MethodNotAllowedError,
  "network_error": NetworkError,
  "not_found": NotFoundError,
  "parse_failed": ParseFailedError,
  "payload_too_large": PayloadTooLargeError,
  "repeat_failure_backoff": RepeatFailureBackoffError,
  "request_cancelled": RequestCancelledError,
  "request_timeout": RequestTimeoutError,
  "server_error": ServerError,
  "service_unavailable": ServiceUnavailableError,
  "session_required": SessionRequiredError,
  "spend_cap_exceeded": SpendCapExceededError,
  "spend_limit_exceeded": SpendLimitExceededError,
  "unauthorized": UnauthorizedError,
  "validation_error": ValidationError,
};

/** Error classes that predate the generator and keep their ancestry. */
export const LEGACY_ERROR_CLASSES: Record<string, string> = {
  "insufficient_credits": "InsufficientFundsError",
  "rate_limit_exceeded": "RateLimitError",
  "rate_limited": "RateLimitError",
};

/** Error class for a code, falling back to the status class. */
export function errorClassFor(
  code: string,
  status: number | undefined,
): ErrorClass {
  return (
    ERROR_CLASSES[code] ??
    (status !== undefined && status < 500 ? ClientError : ServerError)
  );
}

/**
 * Normalise anything thrown by the HTTP client into a typed error. Typed
 * errors and non-HTTP errors pass through; every axios error becomes an
 * `AlterLabError` (or a legacy subclass the caller already built).
 */
export function toTypedError(error: unknown): unknown {
  if (error instanceof AlterLabError) return error;
  if (!isAxiosError(error)) return error;
  const fields = typedErrorFields(error);
  if (fields.code in LEGACY_ERROR_CLASSES) {
    applyTypedFields(error, error);
    return error;
  }
  return new (errorClassFor(fields.code, error.response?.status))(error);
}

